-- -----------------------------------------------------------------------------
-- 5. Seed Tables (12 bàn phục vụ tại 3 khu vực)
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE
    table_number = VALUES(table_number),
    area = VALUES(area),
    seating_capacity = VALUES(seating_capacity),
    status = VALUES(status),
    is_active = VALUES(is_active);

-- -----------------------------------------------------------------------------
-- 6. Seed Mẫu Đơn Hàng & Hóa Đơn (Phục vụ test ngay Swagger & GUI)
-- -----------------------------------------------------------------------------
-- Đơn hàng 1 (Đã hoàn thành & thanh toán)
ON DUPLICATE KEY UPDATE
    status = VALUES(status),
    total_amount = VALUES(total_amount);

ON DUPLICATE KEY UPDATE
    unit_price = VALUES(unit_price),
    subtotal = VALUES(subtotal);

ON DUPLICATE KEY UPDATE
    final_amount = VALUES(final_amount),
    paid_amount = VALUES(paid_amount);

-- Đơn hàng 2 (Đang phục vụ tại Bàn 02)
ON DUPLICATE KEY UPDATE
    status = VALUES(status),
    total_amount = VALUES(total_amount);

ON DUPLICATE KEY UPDATE
    unit_price = VALUES(unit_price),
    subtotal = VALUES(subtotal);

-- -----------------------------------------------------------------------------
-- 7. Seed Audit Logs (Nhật ký mẫu)
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE
    action = VALUES(action);

-- 1. Nạp danh sách đơn hàng
ON DUPLICATE KEY UPDATE total_amount = VALUES(total_amount), status = VALUES(status);

-- 2. Nạp chi tiết món của từng đơn (snapshot unit_price)
ON DUPLICATE KEY UPDATE subtotal = VALUES(subtotal), unit_price = VALUES(unit_price);

-- 3. Nạp hoá đơn tương ứng (khớp 100% doanh thu)
ON DUPLICATE KEY UPDATE final_amount = VALUES(final_amount), paid_amount = VALUES(paid_amount);


-- Hoàn tất sinh 120 đơn hàng và 271 dòng món.
SET FOREIGN_KEY_CHECKS = 1;


